  ($id$sust-f-04$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$easy$diff$, $prompt$Para $\int \frac{dx}{\sqrt{4 - x^2}}$, ¿qué sustitución usas?$prompt$, $json$[{"latex":"x = 2\\sin\\theta","correct":true},{"latex":"x = 2\\tan\\theta","correct":false},{"latex":"x = 2\\sec\\theta","correct":false},{"latex":"x = \\sin\\theta","correct":false}]$json$::jsonb, $exp$$a^2 = 4$, así que $a = 2$ y $x = 2\sin\theta$.$exp$),
  ($id$sust-f-05$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$easy$diff$, $prompt$Para $\int \frac{dx}{\sqrt{9 + x^2}}$, ¿qué sustitución usas?$prompt$, $json$[{"latex":"x = 3\\tan\\theta","correct":true},{"latex":"x = 3\\sin\\theta","correct":false},{"latex":"x = 3\\sec\\theta","correct":false},{"latex":"x = 9\\tan\\theta","correct":false}]$json$::jsonb, $exp$$a^2 = 9$, así que $a = 3$ y $x = 3\tan\theta$.$exp$),
  ($id$sust-m-01$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$medium$diff$, $prompt$¿Qué identidad pitagórica se usa con la sustitución $x = a\sin\theta$?$prompt$, $json$[{"latex":"1 - \\sin^2\\theta = \\cos^2\\theta","correct":true},{"latex":"1 + \\tan^2\\theta = \\sec^2\\theta","correct":false},{"latex":"\\sec^2\\theta - 1 = \\tan^2\\theta","correct":false},{"latex":"\\sin^2\\theta + \\cos^2\\theta = 0","correct":false}]$json$::jsonb, $exp$$a^2 - a^2\sin^2\theta = a^2(1 - \sin^2\theta) = a^2\cos^2\theta$.$exp$),
  ($id$sust-m-02$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$medium$diff$, $prompt$¿Qué identidad pitagórica se usa con la sustitución $x = a\tan\theta$?$prompt$, $json$[{"latex":"1 + \\tan^2\\theta = \\sec^2\\theta","correct":true},{"latex":"1 - \\sin^2\\theta = \\cos^2\\theta","correct":false},{"latex":"\\sec^2\\theta - 1 = \\tan^2\\theta","correct":false},{"latex":"\\tan^2\\theta = \\sin^2\\theta","correct":false}]$json$::jsonb, $exp$$a^2 + a^2\tan^2\theta = a^2(1 + \tan^2\theta) = a^2\sec^2\theta$.$exp$),
  ($id$sust-m-03$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$medium$diff$, $prompt$¿Qué identidad pitagórica se usa con la sustitución $x = a\sec\theta$?$prompt$, $json$[{"latex":"\\sec^2\\theta - 1 = \\tan^2\\theta","correct":true},{"latex":"1 - \\sin^2\\theta = \\cos^2\\theta","correct":false},{"latex":"1 + \\tan^2\\theta = \\sec^2\\theta","correct":false},{"latex":"\\sec^2\\theta + 1 = \\tan^2\\theta","correct":false}]$json$::jsonb, $exp$$a^2\sec^2\theta - a^2 = a^2(\sec^2\theta - 1) = a^2\tan^2\theta$.$exp$),
  ($id$sust-m-04$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$medium$diff$, $prompt$Con $x = 2\sec\theta$, ¿cuánto vale $dx$?$prompt$, $json$[{"latex":"dx = 2\\sec\\theta\\tan\\theta\\,d\\theta","correct":true},{"latex":"dx = 2\\sec^2\\theta\\,d\\theta","correct":false},{"latex":"dx = 2\\tan\\theta\\,d\\theta","correct":false},{"latex":"dx = 2\\cos\\theta\\,d\\theta","correct":false}]$json$::jsonb, $exp$La derivada de $\sec\theta$ es $\sec\theta\tan\theta$.$exp$),
  ($id$sust-m-05$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$medium$diff$, $prompt$En $x = 3\sin\theta$, ¿a qué equivale $\sqrt{9 - x^2}$?$prompt$, $json$[{"latex":"3\\cos\\theta","correct":true},{"latex":"3\\sin\\theta","correct":false},{"latex":"\\cos\\theta","correct":false},{"latex":"9\\cos\\theta","correct":false}]$json$::jsonb, $exp$$\sqrt{9 - 9\sin^2\theta} = \sqrt{9\cos^2\theta} = 3\cos\theta$ (con $\cos\theta \geq 0$).$exp$)
INSERT INTO public.questions (id, section_id, subtema_id, law_id, difficulty, prompt, options, explanation)
VALUES
  ($id$sust-m-06$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$medium$diff$, $prompt$¿Qué sustitución transforma $\frac{dx}{x^2 + 4}$ en una integral trigonométrica?$prompt$, $json$[{"latex":"x = 2\\tan\\theta","correct":true},{"latex":"x = 2\\sin\\theta","correct":false},{"latex":"x = 2\\sec\\theta","correct":false},{"latex":"x = 4\\tan\\theta","correct":false}]$json$::jsonb, $exp$El denominador es $x^2 + 4 = x^2 + a^2$, con $a = 2$: $x = 2\tan\theta$.$exp$),
  ($id$sust-h-01$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$hard$diff$, $prompt$Calcula $\int \frac{dx}{x^2 + 4}$ usando $x = 2\tan\theta$.$prompt$, $json$[{"latex":"\\frac{1}{2}\\arctan\\frac{x}{2} + C","correct":true},{"latex":"\\arctan\\frac{x}{2} + C","correct":false},{"latex":"\\frac{1}{4}\\arctan x + C","correct":false},{"latex":"\\ln(x^2 + 4) + C","correct":false}]$json$::jsonb, $exp$$dx = 2\sec^2\theta\,d\theta$; la integral da $\frac{1}{2}\theta + C = \frac{1}{2}\arctan\frac{x}{2} + C$.$exp$),
  ($id$sust-h-02$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$hard$diff$, $prompt$Calcula $\int \frac{dx}{\sqrt{9 - x^2}}$ usando $x = 3\sin\theta$.$prompt$, $json$[{"latex":"\\arcsin\\frac{x}{3} + C","correct":true},{"latex":"\\arcsin\\frac{x}{9} + C","correct":false},{"latex":"\\frac{1}{3}\\arcsin x + C","correct":false},{"latex":"\\arccos\\frac{x}{3} + C","correct":false}]$json$::jsonb, $exp$$\int d\theta = \theta + C = \arcsin\frac{x}{3} + C$.$exp$),
  ($id$sust-h-03$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$hard$diff$, $prompt$Calcula $\int \frac{dx}{x\sqrt{x^2 - 9}}$ usando $x = 3\sec\theta$.$prompt$, $json$[{"latex":"\\frac{1}{3}\\operatorname{arcsec}\\frac{x}{3} + C","correct":true},{"latex":"\\operatorname{arcsec}\\frac{x}{3} + C","correct":false},{"latex":"\\frac{1}{3}\\arctan\\frac{x}{3} + C","correct":false},{"latex":"\\frac{1}{3}\\ln\\left|x + \\sqrt{x^2-9}\\right| + C","correct":false}]$json$::jsonb, $exp$Simplifica a $\int\frac{1}{3}\,d\theta = \frac{1}{3}\theta + C = \frac{1}{3}\operatorname{arcsec}\frac{x}{3} + C$.$exp$),
  ($id$sust-h-04$id$, $sec$calculo-integral$sec$, $sub$sustitucion-trigonometrica$sub$, $law$sustitucion-trigonometrica$law$, $diff$hard$diff$, $prompt$¿Para qué se usa principalmente la sustitución trigonométrica?$prompt$, $json$[{"latex":"\\text{Eliminar raíces cuadradas usando identidades pitagóricas}","correct":true},{"latex":"\\text{Convertir logaritmos en potencias}","correct":false},{"latex":"\\text{Derivar funciones compuestas}","correct":false},{"latex":"\\text{Resolver ecuaciones diferenciales lineales}","correct":false}]$json$::jsonb, $exp$Convierte $\sqrt{a^2 \pm x^2}$ o $\sqrt{x^2 - a^2}$ en expresiones trigonométricas sin raíz.$exp$)
